% Problem-section file following ../_template.tex.
\section{Optimal CGLMP measurements for a maximally entangled state}
\label{sec:problem-24}

\paragraph{Problem.}
For every $d\geq3$, do the standard Fourier--phase measurements optimize the
CGLMP violation of the maximally entangled state among all projective
$d$-outcome measurements?  Fix the state
\begin{equation}
  \lvert\Phi_d\rangle
  =\frac{1}{\sqrt d}\sum_{j=0}^{d-1}\lvert j,j\rangle.
  \label{eq:p24-maximally-entangled-state}
\end{equation}
Equation~\eqref{eq:p24-maximally-entangled-state} is held fixed; the shared
state is not part of the optimization.

For outcomes in $\mathbb Z_d$, let $[t]_d\in\{0,\ldots,d-1\}$ be the residue
of $t$ and define the CGLMP functional by
\begin{equation}
  \begin{aligned}
    B_d={}&\mathbb E([A_0-B_0]_d)+\mathbb E([B_0-A_1]_d)\\
          &+\mathbb E([A_1-B_1]_d)+\mathbb E([B_1-A_0-1]_d).
  \end{aligned}
  \label{eq:p24-cglmp-functional}
\end{equation}
Local behaviors satisfy $B_d\geq d-1$ under the convention in
Eq.~\eqref{eq:p24-cglmp-functional}.  The candidate measurements have bases
\begin{equation}
  \begin{aligned}
    \lvert a;x\rangle
      &=\frac{1}{\sqrt d}\sum_{j=0}^{d-1}
        \exp\!\left(\frac{2\pi i}{d}j(a+\alpha_x)\right)\lvert j\rangle,\\
    \lvert b;y\rangle
      &=\frac{1}{\sqrt d}\sum_{j=0}^{d-1}
        \exp\!\left(\frac{2\pi i}{d}j(-b+\beta_y)\right)\lvert j\rangle,
  \end{aligned}
  \label{eq:p24-cglmp-bases}
\end{equation}
with $\alpha_0=0$, $\alpha_1=-1/2$, $\beta_0=1/4$, and $\beta_1=3/4$.
The question is whether the bases in Eq.~\eqref{eq:p24-cglmp-bases} minimize
Eq.~\eqref{eq:p24-cglmp-functional} on
Eq.~\eqref{eq:p24-maximally-entangled-state}, up to symmetries of the state
and functional.

\subsection*{Status}

Unsolved

\subsection*{Source}

Zohren and Gill formulate the standard Fourier-phase measurements as the
candidate global optimizers of the CGLMP value for a fixed maximally entangled
state \sourcecite{ref:p24-zohren-gill}{ZG08}.

\subsection*{Progress}

\begin{itemize}
  \item Collins, Gisin, Linden, Massar, and Popescu introduced the
  high-dimensional Bell family and the Fourier--phase measurement
  construction underlying Eq.~\eqref{eq:p24-cglmp-bases}
  \sourcecite{ref:p24-cglmp}{CGLMP02}.

  \item Zohren and Gill explicitly identify optimality of
  Eq.~\eqref{eq:p24-cglmp-bases} for the fixed state in
  Eq.~\eqref{eq:p24-maximally-entangled-state} as a longstanding conjecture
  and provide numerical support.  They do not prove it for arbitrary $d$
  \sourcecite{ref:p24-zohren-gill}{ZG08}.

  \item For $d=3$, Lang, Vértesi, and Navascués obtained a semidefinite upper
  bound on the optimum over maximally entangled states that differs from the
  candidate value by about $10^{-10}$.  This numerical certification is not
  an exact proof and does not address all dimensions
  \sourcecite{ref:p24-lang}{LVN14}.
\end{itemize}

